/**
 * @summary Get reports data for charts
 */
export const getGetReportsDataUrl = (params?: GetReportsDataParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/reports/data?${stringifiedParams}`
    : `/api/reports/data`;
};

export const getReportsData = async (
  params?: GetReportsDataParams,
  options?: RequestInit,
): Promise<ReportsData> => {
  return customFetch<ReportsData>(getGetReportsDataUrl(params), {
    ...options,
    method: "GET",
  });
};

